 55	            ) ?? false
 56	          );
 57	        } catch {
 58	          return false;
 59	        }
 60	      });
 61	
 62	      const enriched = todayTasks.map((item: any) => {
 63	        const workingAction: any[] = Array.isArray(item.WorkingAction)
 64	          ? item.WorkingAction
 65	          : (globalCommon.parseJSON(item.WorkingAction) || []);
 66	        const workingDetails = workingAction.find((wa: any) => wa.Title === 'WorkingDetails');
