/**
 * Ensures the unfiltered full Master Tasks dump for a site.
 * Whichever page opens first (Team Portfolio, PXC Overview, …) owns the
 * network call; every other page joins in-flight or reads from cache.
 */
const ensureMasterListFullDump = async (
    props: IMasterTaskListProps,
    itemTypes?: ReadonlySet<string>
): Promise<any[]> => {
    const include = itemTypes ? (row: any) => itemTypes.has(row?.Item_x0020_Type) : undefined;
    const siteKey = masterListSiteKey(props.siteUrl);
    const fullKey = masterListFullKey(props.siteUrl);

    const cached = masterListFullRaw.get(siteKey);
    if (cached && masterListFresh(cached.loadedAt)) {
        return cloneRows(cached.rows, include);
    }

    let pending = masterListRawInFlight.get(fullKey);
    if (!pending) {
        pending = fetchMasterTaskListNetwork(props, '').then((rows) => {
            masterListFullRaw.set(siteKey, { rows, loadedAt: Date.now() });
            return rows;
        });
        masterListRawInFlight.set(fullKey, pending);
        pending.then(
            () => masterListRawInFlight.delete(fullKey),
            () => masterListRawInFlight.delete(fullKey)
        );
    }
    // Store the complete response; only the caller's copy is restricted by type.
    return pending.then((rows) => cloneRows(rows, include));
};

/**
 * Public entry: Team Portfolio GetComponents, or any page needing raw rows.
 * Unfiltered → shared full dump (cache / single in-flight).
 * Filtered (portfolio type tab) → separate keyed fetch; does not overwrite full dump.
 */
export const fetchMasterTaskListRaw = async (
    props: IMasterTaskListProps,
    filter: string = ''
): Promise<any[]> => {
    const isFull = !filter || filter.trim() === '';
    if (isFull) {
        return ensureMasterListFullDump(props);
    }

    const filteredKey = masterListFilteredKey(props.siteUrl, filter);
    let pending = masterListRawInFlight.get(filteredKey);
    if (!pending) {
        pending = fetchMasterTaskListNetwork(props, filter);
        masterListRawInFlight.set(filteredKey, pending);
        pending.then(
            () => masterListRawInFlight.delete(filteredKey),
            () => masterListRawInFlight.delete(filteredKey)
        );
    }
    return pending.then((rows) => cloneMasterList(rows));
};

/**
 * @deprecated Prefer fetchMasterTaskListRaw — kept for call-site compatibility.
 */
export const ensureTeamPortfolioMasterList = async (
    siteUrl: string,
    filter: string,
    fetcher: () => Promise<any[]>
): Promise<any[]> => {
    const isFull = !filter || filter.trim() === '';
    if (isFull) {
        const siteKey = masterListSiteKey(siteUrl);
        const cached = masterListFullRaw.get(siteKey);
        if (cached && masterListFresh(cached.loadedAt)) {
            return cloneMasterList(cached.rows);
        }
        const fullKey = masterListFullKey(siteUrl);
        const inflight = masterListRawInFlight.get(fullKey);
        if (inflight) {
            return inflight.then((rows) => cloneMasterList(rows));
        }
    }
    const key = isFull ? masterListFullKey(siteUrl) : masterListFilteredKey(siteUrl, filter);
    let pending = masterListRawInFlight.get(key);
    if (!pending) {
        pending = (async () => {
            const rows = await fetcher();
            if (isFull) {
                masterListFullRaw.set(masterListSiteKey(siteUrl), { rows, loadedAt: Date.now() });
            }
            return rows;
        })();
        masterListRawInFlight.set(key, pending);
        pending.then(
            () => masterListRawInFlight.delete(key),
            () => masterListRawInFlight.delete(key)
        );
    }
    return pending.then((rows) => cloneMasterList(rows));
};
